295→  public string? Commit(string? message = null, long? timestampMillis = null)
296→  {
297→    ThrowIfDisposed();
298→    using var options = new Native.AutomergeCommitOptions
299→    {
300→      message = message is null
301→        ? Native.OptionUtf8String.None
302→        : Native.OptionUtf8String.Some(Native.Utf8String.From(message)),
303→      timestamp_millis = timestampMillis.HasValue
304→        ? Native.OptionI64.Some(timestampMillis.Value)
305→        : Native.OptionI64.None
306→    };
