336→  /// <summary>
337→  /// Saves all changes made after the specified heads.
338→  /// </summary>
339→  /// <remarks>
340→  /// <para>
341→  /// This method is used by the Storage subsystem to save incremental changes
342→  /// relative to known document heads. Unlike <see cref="SaveIncremental"/>,
343→  /// which uses an internal cursor, this method provides explicit control over
344→  /// what changes to save.
345→  /// </para>
346→  /// <para>
347→  /// Typical usage:
348→  /// </para>
349→  /// <list type="number">
350→  /// <item>Load document and record heads: <c>var baseHeads = doc.GetHeads()</c></item>
351→  /// <item>Make changes and commit</item>
352→  /// <item>Save only new changes: <c>var incremental = doc.SaveAfter(baseHeads)</c></item>
353→  /// <item>Load later with: <c>doc.LoadIncremental(incremental)</c></item>
354→  /// </list>
355→  /// <para>
356→  /// This corresponds to the TypeScript <c>A.saveSince(doc, heads)</c> API and is
357→  /// critical for efficient storage subsystem operations.
358→  /// </para>
359→  /// </remarks>
360→  /// <param name="heads">The heads representing the baseline state. Pass empty collection to save all changes.</param>
361→  /// <returns>Binary data containing changes made after the specified heads. Returns empty array if no new changes.</returns>
362→  /// <exception cref="ArgumentNullException">Thrown when heads is null.</exception>
363→  /// <exception cref="ArgumentException">Thrown when heads contains invalid hash strings.</exception>
364→  /// <exception cref="ObjectDisposedException">Thrown when the document has been disposed.</exception>
365→  [PublicAPI]
366→  public byte[] SaveAfter(IEnumerable<string> heads)
367→  {
368→    if(heads is null)
369→    {
370→      throw new ArgumentNullException(nameof(heads));
371→    }
372→
373→    ThrowIfDisposed();
374→
375→    var headArray = heads.ToArray();
376→
377→    // Empty heads is valid - it means "save all changes from the beginning"
378→    // (equivalent to save_after(&[]) in Rust)
379→    var hashes = new Native.ChangeHashBytes[headArray.Length];
380→    for(var i = 0; i < headArray.Length; i++)
381→    {
382→      try
383→      {
384→        hashes[i] = ParseHash(headArray[i]);
385→      }
386→      catch(ArgumentException ex)
387→      {
388→        throw new ArgumentException($"Invalid hash at index {i}: {ex.Message}", nameof(heads), ex);
389→      }
390→    }
391→
392→    using var slice = Native.SliceChangeHashBytes.From(hashes);
393→    using var bytes = _doc.SaveAfter(slice);
394→    return bytes.AsManagedBytes();
395→  }
