  }

  var list = ToNativeObjectId(listId);
  try
  {
    var nativeValues = new Native.AutomergeScalarValue[values.Count];
    for(int i = 0; i < values.Count; i++)
    {
      nativeValues[i] = CreateNativeScalar(values[i]);
    }

