2083→  static Native.AutomergeSpan ConvertToNativeSpan(AutomergeSpan span)
2084→  {
2085→    if(span is AutomergeTextSpan textSpan)
2086→    {
2087→      var nativeMarks = new Native.AutomergeMarkData[textSpan.Marks.Count];
2088→      for(var i = 0; i < textSpan.Marks.Count; i++)
2089→      {
2090→        var mark = textSpan.Marks[i];
2091→        nativeMarks[i] = new Native.AutomergeMarkData
2092→        {
2093→          name = Native.Utf8String.From(mark.Name),
2094→          value = CreateScalarFromMarkInfo(mark)
2095→        };
2096→      }
2097→
2098→      return new Native.AutomergeSpan
2099→      {
2100→        kind = Native.AutomergeSpanKind.Text,
2101→        text = Native.Utf8String.From(textSpan.Text),
2102→        marks = nativeMarks.Length > 0
2103→          ? Native.VecAutomergeMarkData.From(nativeMarks)
2104→          : Native.VecAutomergeMarkData.Empty(),
2105→        block_obj_id = new Native.AutomergeObjId { bytes = Native.VecU8.Empty() },
2106→        block_type = Native.Utf8String.From(string.Empty),
2107→        block_parents = Native.VecUtf8String.Empty(),
2108→        block_attrs_json = Native.Utf8String.From(string.Empty)
2109→      };
2110→    }
2111→
2112→    if(span is AutomergeBlockSpan blockSpan)
2113→    {
2114→      var parentStrings = new Native.Utf8String[blockSpan.Parents.Count];
2115→      for(var i = 0; i < blockSpan.Parents.Count; i++)
2116→      {
2117→        parentStrings[i] = Native.Utf8String.From(blockSpan.Parents[i]);
2118→      }
2119→
2120→      return new Native.AutomergeSpan
2121→      {
2122→        kind = Native.AutomergeSpanKind.Block,
2123→        text = Native.Utf8String.From(string.Empty),
2124→        marks = Native.VecAutomergeMarkData.Empty(),
2125→        block_obj_id = new Native.AutomergeObjId { bytes = Native.VecU8.Empty() },
2126→        block_type = Native.Utf8String.From(blockSpan.BlockType),
2127→        block_parents = parentStrings.Length > 0
2128→          ? Native.VecUtf8String.From(parentStrings)
2129→          : Native.VecUtf8String.Empty(),
2130→        block_attrs_json = Native.Utf8String.From(blockSpan.AttributesJson ?? "{}")
