{
  ThrowIfDisposed();

  using var vec = _doc.TopoHistoryTraversal();
  var results = new List<string>(vec.Count);
  for(var i = 0; i < vec.Count; i++)
  {
    var hash = vec[i];
    results.Add(ConvertHashToHex(hash));
  }

  return results;
}

